use std::path::{Path,PathBuf};use notifyredirect_core::Result;
pub fn app_db()->Result<PathBuf>{let base=std::env::var_os("LOCALAPPDATA").ok_or("缺少本地数据目录")?;Ok(PathBuf::from(base).join("NotifyRedirectNative").join("notifyredirect.db"))}
pub fn cli_db(explicit:Option<&Path>)->Result<PathBuf>{if let Some(p)=explicit{return Ok(p.join("notifyredirect.db"))}let direct=app_db()?;if direct.is_file(){return Ok(direct)}let packages=std::path::PathBuf::from(std::env::var_os("LOCALAPPDATA").ok_or("缺少本地目录")?).join("Packages");let mut matches=vec![];if let Ok(items)=std::fs::read_dir(packages){for item in items.flatten(){if item.file_name().to_string_lossy().starts_with("NotifyRedirect.Native_"){let p=item.path().join("LocalCache/Local/NotifyRedirectNative/notifyredirect.db");if p.is_file(){matches.push(p)}}}}if matches.len()==1{Ok(matches.remove(0))}else{Err("请运行新版桌面程序并启用 Agent 入口；多实例请指定 --data-dir".into())}}
